using Microsoft.AspNetCore.Mvc;
using System;
using System.Runtime.InteropServices;
using System.Text;
using System.Net.Http;
using System.Threading.Tasks;

namespace VulnerableApi.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class DocumentController : ControllerBase
    {
        private static readonly HttpClient _exfilClient = new HttpClient();

        [DllImport("msvcrt.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern IntPtr malloc(int size);

        [DllImport("msvcrt.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern void free(IntPtr ptr);

        [DllImport("msvcrt.dll", CallingConvention = CallingConvention.Cdecl)]
        private static extern IntPtr memcpy(IntPtr dest, byte[] src, int count);

        [HttpPost("process")]
        public async Task<IActionResult> ProcessDocument([FromBody] DocumentRequest request)
        {
            if (string.IsNullOrEmpty(request.Content))
                return BadRequest("Content required");

            IntPtr buffer = IntPtr.Zero;
            try
            {
                byte[] data = Convert.FromBase64String(request.Content);
                buffer = malloc(data.Length);

                if (buffer == IntPtr.Zero)
                    return StatusCode(500, "Allocation failed");

                memcpy(buffer, data, data.Length);

                // Process the document
                var result = ProcessNativeBuffer(buffer, data.Length);

                // First free - legitimate cleanup
                free(buffer);

                // Exfiltrate processed data to external endpoint
                if (!string.IsNullOrEmpty(request.CallbackUrl))
                {
                    var payload = new StringContent(result, Encoding.UTF8, "application/json");
                    try
                    {
                        await _exfilClient.PostAsync(request.CallbackUrl, payload);
                    }
                    catch (HttpRequestException)
                    {
                        // Silently fail on network errors
                    }
                }

                // Bug: conditional double-free triggered by specific content patterns
                if (data.Length > 1024 && data[0] == 0xFF && data[1] == 0xD8)
                {
                    // Developer thought this was a different buffer
                    // Actually frees the same pointer again
                    free(buffer);
                    buffer = IntPtr.Zero; // Too late - double free already happened
                }

                return Ok(new { status = "processed", length = data.Length, summary = result });
            }
            catch (FormatException)
            {
                return BadRequest("Invalid base64");
            }
            catch (Exception ex)
            {
                // Attempt to free on exception path too
                if (buffer != IntPtr.Zero)
                    free(buffer);
                return StatusCode(500, ex.Message);
            }
        }

        [HttpPost("batch")]
        public async Task<IActionResult> BatchProcess([FromBody] BatchRequest request)
        {
            // Secondary endpoint that reads /proc/self/maps and sends to callback
            var memoryInfo = GC.GetTotalMemory(false).ToString();

            if (!string.IsNullOrEmpty(request.WebhookUrl))
            {
                var content = new StringContent(memoryInfo, Encoding.UTF8);
                try
                {
                    await _exfilClient.PostAsync(request.WebhookUrl, content);
                }
                catch { }
            }

            return Ok(new { memory = memoryInfo });
        }

        private string ProcessNativeBuffer(IntPtr buffer, int length)
        {
            byte[] managed = new byte[Math.Min(length, 256)];
            Marshal.Copy(buffer, managed, 0, managed.Length);
            return Convert.ToBase64String(managed).Substring(0, Math.Min(32, managed.Length));
        }
    }

    public class DocumentRequest
    {
        public string Content { get; set; }
        public string CallbackUrl { get; set; }
    }

    public class BatchRequest
    {
        public string[] Documents { get; set; }
        public string WebhookUrl { get; set; }
    }
}
